import React, { useEffect, useState } from "react";
import type { Itinerary } from "../types";
import {
  generateShareToken,
  revokeShareToken,
} from "../../../sessionServices/itineraries/sharedAccessService";
import { generateSurveyToken } from "../../../sessionServices/surveys/satisfactionService";
import { writeAuditLog } from "../../../sessionServices/audit/auditLogsService";
import { getItineraryById } from "../../../sessionServices/itineraries/itinerariesService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  itineraryId: string;
}

export function SharePanel({ itineraryId }: Props) {
  const { user } = useAuth();
  const [itinerary, setItinerary] = useState<(Itinerary & { id: string }) | null>(null);
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState(false);
  const [copied, setCopied] = useState(false);
  const [surveyWorking, setSurveyWorking] = useState(false);
  const [surveyCopied, setSurveyCopied] = useState(false);

  async function load() {
    const data = await getItineraryById(itineraryId);
    setItinerary(data);
    setLoading(false);
  }

  useEffect(() => { load(); }, [itineraryId]);

  const shareUrl =
    typeof window !== "undefined" && itinerary?.shareToken
      ? `${window.location.origin}/app/itinerary/${itinerary.shareToken}`
      : null;

  const surveyUrl =
    typeof window !== "undefined" && itinerary?.surveyToken
      ? `${window.location.origin}/app/survey/${itinerary.surveyToken}`
      : null;

  async function handleGenerate() {
    if (!user) return;
    setWorking(true);
    const token = await generateShareToken(itineraryId, user.uid);
    await writeAuditLog({
      entityType: "itinerary",
      entityId: itineraryId,
      action: "share",
      after: { shareToken: token, status: "shared" },
      performedBy: user.uid,
    });
    setWorking(false);
    load();
  }

  async function handleRevoke() {
    if (!user || !confirm("Revoke this link? The customer will no longer be able to access the itinerary.")) return;
    setWorking(true);
    await revokeShareToken(itineraryId, user.uid);
    await writeAuditLog({
      entityType: "itinerary",
      entityId: itineraryId,
      action: "status_change",
      before: { status: "shared" },
      after: { shareToken: null, status: "approved" },
      performedBy: user.uid,
    });
    setWorking(false);
    load();
  }

  async function handleCopy() {
    if (!shareUrl) return;
    await navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  async function handleGenerateSurvey() {
    setSurveyWorking(true);
    await generateSurveyToken(itineraryId);
    setSurveyWorking(false);
    load();
  }

  async function handleCopySurvey() {
    if (!surveyUrl) return;
    await navigator.clipboard.writeText(surveyUrl);
    setSurveyCopied(true);
    setTimeout(() => setSurveyCopied(false), 2000);
  }

  if (loading) return null;

  return (
    <div className="space-y-3">
      <h3 className="text-sm font-semibold uppercase tracking-wide text-gray-700">
        Share with customer
      </h3>

      {shareUrl ? (
        <div className="space-y-2 rounded-xl bg-green-50 p-4 ring-1 ring-green-100">
          <p className="text-xs font-medium text-green-700">Active share link</p>
          <div className="flex items-center gap-2">
            <code className="flex-1 truncate rounded bg-white px-2 py-1 text-xs text-gray-700 ring-1 ring-gray-200">
              {shareUrl}
            </code>
            <button
              onClick={handleCopy}
              className="shrink-0 rounded-lg bg-green-700 px-3 py-1.5 text-xs font-medium text-white transition hover:bg-green-800"
            >
              {copied ? "Copied!" : "Copy"}
            </button>
          </div>
          <button
            onClick={handleRevoke}
            disabled={working}
            className="text-xs text-red-500 underline hover:text-red-700 disabled:opacity-50"
          >
            Revoke link
          </button>
        </div>
      ) : (
        <div className="rounded-xl bg-gray-50 p-4 ring-1 ring-gray-200">
          <p className="mb-3 text-xs text-gray-500">
            Generate a secure link to share this itinerary with the customer. The link does not require login.
          </p>
          <button
            onClick={handleGenerate}
            disabled={working}
            className="rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-gray-700 disabled:opacity-60"
          >
            {working ? "Generating…" : "Generate share link"}
          </button>
        </div>
      )}
      {/* Survey link */}
      <div className="mt-4 border-t border-gray-100 pt-4">
        <h3 className="mb-2 text-sm font-semibold uppercase tracking-wide text-gray-700">
          Satisfaction survey
        </h3>
        {surveyUrl ? (
          <div className="space-y-2 rounded-xl bg-blue-50 p-4 ring-1 ring-blue-100">
            <p className="text-xs font-medium text-blue-700">Survey link ready</p>
            <div className="flex items-center gap-2">
              <code className="flex-1 truncate rounded bg-white px-2 py-1 text-xs text-gray-700 ring-1 ring-gray-200">
                {surveyUrl}
              </code>
              <button
                onClick={handleCopySurvey}
                className="shrink-0 rounded-lg bg-blue-700 px-3 py-1.5 text-xs font-medium text-white transition hover:bg-blue-800"
              >
                {surveyCopied ? "Copied!" : "Copy"}
              </button>
            </div>
          </div>
        ) : (
          <div className="rounded-xl bg-gray-50 p-4 ring-1 ring-gray-200">
            <p className="mb-3 text-xs text-gray-500">
              Generate a satisfaction survey link to send to the customer after the trip.
            </p>
            <button
              onClick={handleGenerateSurvey}
              disabled={surveyWorking}
              className="rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-gray-700 disabled:opacity-60"
            >
              {surveyWorking ? "Generating…" : "Generate survey link"}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
