import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  getDoc,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  Timestamp,
  updateDoc,
  where,
} from "firebase/firestore";
import type { Itinerary, ItineraryStatus } from "../../features/admin/types";

export type CreateItineraryInput = {
  userId: string;
  title: string;
  summary: string;
  originCity?: string;
  destinationCities: string[];
  startDate: string;
  endDate: string;
  travelerCount: number;
  tripType?: string;
  budget?: number;
  preferences?: string[];
  internalNotes?: string;
  travelerEmail?: string;
  createdBy: string;
};

export type UpdateItineraryInput = Partial<
  Omit<CreateItineraryInput, "createdBy" | "userId">
> & { updatedBy: string; status?: ItineraryStatus };

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

function localDateStringToDate(dateStr: string): Date {
  const [year, month, day] = dateStr.split("-").map(Number);
  return new Date(year, month - 1, day);
}

export async function createItinerary(input: CreateItineraryInput): Promise<string> {
  const db = await getDb();
  const ref = await addDoc(collection(db, "itineraries"), {
    userId: input.userId,
    title: input.title,
    summary: input.summary,
    status: "draft" as ItineraryStatus,
    originCity: input.originCity ?? null,
    destinationCities: input.destinationCities,
    startDate: Timestamp.fromDate(localDateStringToDate(input.startDate)),
    endDate: Timestamp.fromDate(localDateStringToDate(input.endDate)),
    travelerCount: input.travelerCount,
    tripType: input.tripType ?? null,
    budget: input.budget ?? null,
    preferences: input.preferences ?? [],
    internalNotes: input.internalNotes ?? null,
    travelerEmail: input.travelerEmail ?? null,
    emailSentDates: {},
    shareToken: null,
    sharedAt: null,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
    createdBy: input.createdBy,
    updatedBy: null,
  });
  return ref.id;
}

export async function updateItinerary(id: string, input: UpdateItineraryInput): Promise<void> {
  const db = await getDb();
  const { startDate, endDate, ...rest } = input;
  const payload: Record<string, unknown> = { updatedAt: serverTimestamp() };
  for (const [key, value] of Object.entries(rest)) {
    payload[key] = value ?? null;
  }
  if (startDate) payload["startDate"] = Timestamp.fromDate(localDateStringToDate(startDate));
  if (endDate) payload["endDate"] = Timestamp.fromDate(localDateStringToDate(endDate));
  await updateDoc(doc(db, "itineraries", id), payload);
}

export async function getItineraryById(id: string): Promise<(Itinerary & { id: string }) | null> {
  const db = await getDb();
  const snap = await getDoc(doc(db, "itineraries", id));
  if (!snap.exists()) return null;
  return { id: snap.id, ...(snap.data() as Itinerary) };
}

export async function listItineraries(): Promise<(Itinerary & { id: string })[]> {
  const db = await getDb();
  const q = query(collection(db, "itineraries"), orderBy("createdAt", "desc"));
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Itinerary) }));
}

export async function listItinerariesByUser(userId: string): Promise<(Itinerary & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "itineraries"),
    where("userId", "==", userId),
    orderBy("createdAt", "desc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Itinerary) }));
}

export async function deleteItinerary(id: string): Promise<void> {
  const db = await getDb();
  await deleteDoc(doc(db, "itineraries", id));
}
