import React, { useState } from "react";
import type { ItineraryDay } from "../types";
import {
  createDay,
  updateDay,
} from "../../../sessionServices/itineraries/itineraryDaysService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  itineraryId: string;
  nextDayNumber: number;
  existing?: ItineraryDay & { id: string };
  onSaved: () => void;
  onCancel: () => void;
}

export function ItineraryDayForm({ itineraryId, nextDayNumber, existing, onSaved, onCancel }: Props) {
  const { user } = useAuth();
  const isEditing = Boolean(existing);

  const [form, setForm] = useState({
    date: existing ? tsToDateInput(existing.date) : "",
    city: existing?.city ?? "",
    title: existing?.title ?? "",
    notes: existing?.notes ?? "",
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function set(field: keyof typeof form, value: string) {
    setForm((prev) => ({ ...prev, [field]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;
    setError(null);
    setSaving(true);
    try {
      if (isEditing && existing) {
        await updateDay(existing.id, {
          date: form.date,
          city: form.city,
          title: form.title || undefined,
          notes: form.notes || undefined,
          updatedBy: user.uid,
        });
      } else {
        await createDay({
          itineraryId,
          dayNumber: nextDayNumber,
          date: form.date,
          city: form.city,
          title: form.title || undefined,
          notes: form.notes || undefined,
          createdBy: user.uid,
        });
      }
      onSaved();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-3 rounded-xl bg-gray-50 p-4 ring-1 ring-gray-200">
      <p className="text-sm font-medium text-gray-700">
        {isEditing ? "Edit day" : `Day ${nextDayNumber}`}
      </p>
      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Date *</label>
          <input
            type="date"
            required
            value={form.date}
            onChange={(e) => set("date", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">City *</label>
          <input
            type="text"
            required
            value={form.city}
            onChange={(e) => set("city", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Title</label>
          <input
            type="text"
            value={form.title}
            onChange={(e) => set("title", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Notes</label>
          <input
            type="text"
            value={form.notes}
            onChange={(e) => set("notes", e.target.value)}
            className={inputClass}
          />
        </div>
      </div>
      {error && <p className="text-xs text-red-600">{error}</p>}
      <div className="flex gap-2">
        <button
          type="submit"
          disabled={saving}
          className="rounded-lg bg-gray-900 px-4 py-1.5 text-xs font-medium text-white disabled:opacity-60"
        >
          {saving ? "Saving..." : "Save day"}
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="rounded-lg border border-gray-300 px-4 py-1.5 text-xs font-medium text-gray-600"
        >
          Cancel
        </button>
      </div>
    </form>
  );
}

function tsToDateInput(ts: unknown): string {
  try {
    const date = (ts as { toDate: () => Date }).toDate();
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, "0");
    const d = String(date.getDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  } catch {
    return "";
  }
}

const inputClass =
  "block w-full rounded-lg border border-gray-300 px-3 py-1.5 text-sm text-gray-900 focus:border-gray-800 focus:outline-none focus:ring-1 focus:ring-gray-800";
